<?php require 'config.php';$u=require_login();require_innovations();page_start('Daily challenge',$u);heading('ONE SMALL BUILD, EVERY DAY','Turn curiosity into practice.','Submit code or a written approach. A community administrator reviews it; submitted code is never executed.');$challenge=daily_challenge();$mine=one('SELECT * FROM challenge_submissions WHERE user_id=? AND challenge_date=?',[$u['id'],date('Y-m-d')]); ?>
<div class="two-col"><section class="card challenge-card"><span class="badge"><?=e(date('l, d M Y'))?> · Africa/Freetown</span><h2><?=e($challenge['title']??'No active challenge')?></h2><p class="body-text"><?=e($challenge['prompt']??'Please check with an organiser.')?></p><p class="meta">One daily submission per member. You can revise it until approved. No credentials or personal data, please.</p>
<?php if($challenge):?><form method="post" action="innovate.php"><?php innovation_hidden('submit_challenge',(int)$challenge['id']);?><label>Your solution or approach<textarea class="code-input" name="solution" rows="10" maxlength="12000" required><?=e($mine['solution']??'')?></textarea></label><button class="button" <?=$mine&&$mine['status']==='approved'?'disabled':''?>><?=$mine?'Update submission':'Submit my solution'?></button></form><?php endif;?></section>
<aside><section class="card"><p class="eyebrow">YOUR REVIEW STATUS</p><h2><?=e($mine?ucfirst(str_replace('_',' ',$mine['status'])):'Ready when you are.')?></h2><p class="body-text"><?=e($mine['review']??'Submissions receive a manual review. A submitted solution is not automatically marked correct.')?></p></section><section class="card"><h2>A useful rhythm.</h2><p>Read the prompt. Try a small solution. Explain your decisions. Come back tomorrow for another challenge.</p><a href="achievements.php">View your learning streak →</a></section></aside></div>
<section class="card"><h2>Your submission history</h2><?php foreach(rows('SELECT s.*,c.title FROM challenge_submissions s JOIN challenges c ON c.id=s.challenge_id WHERE s.user_id=? ORDER BY s.challenge_date DESC LIMIT 30',[$u['id']]) as $s):?><details><summary><?=e($s['challenge_date'].' / '.$s['title'].' / '.str_replace('_',' ',$s['status']))?></summary><pre class="code-block"><?=e($s['solution'])?></pre><p class="body-text"><?=e($s['review']??'Awaiting review')?></p></details><?php endforeach;?></section>
<?php if($u['role']==='admin'):?><section class="card"><h2>Challenge review desk</h2><p>Review manually. Never paste untrusted submissions into your terminal.</p><?php foreach(rows('SELECT s.*,u.name,c.title FROM challenge_submissions s JOIN users u ON u.id=s.user_id JOIN challenges c ON c.id=s.challenge_id ORDER BY s.id DESC LIMIT 40') as $s):?><details><summary><?=e($s['name'].' / '.$s['title'].' / '.$s['status'])?></summary><pre class="code-block"><?=e($s['solution'])?></pre><form method="post" action="innovate.php"><?php innovation_hidden('review_challenge',(int)$s['id']);?><label>Review feedback<textarea name="review" required maxlength="1000"><?=e($s['review']??'')?></textarea></label><label>Decision<select name="status"><option value="approved">Approved</option><option value="needs_work">Needs work</option></select></label><button class="button">Save review</button></form></details><?php endforeach;?></section><details><summary>+ Add a challenge to the daily rotation</summary><form class="card" method="post" action="innovate.php"><?php innovation_hidden('save_challenge');input('Challenge title','title');textarea('Challenge prompt','prompt');?><label>Difficulty<select name="difficulty"><option>Beginner</option><option>Intermediate</option></select></label><button class="button">Publish challenge</button></form></details><?php endif;page_end(); ?>